SELECT * FROM ( SELECT COUNT(*) OVER() AS TOTAL_RECORD_COUNT, TB.* FROM ( SELECT ROW_NUMBER() OVER (ORDER BY REQUST_NO DESC) AS RNUM , PROGRM_FILE_NM AS "progrmFileNm" , REQUST_NO AS "rqesterNo" , RQESTER_ID AS "rqesterPersonId" , CONCAT(SUBSTRING(CHANGE_REQUST_CN FROM 1 FOR 10), '...') AS "changerqesterCn" , CONCAT(SUBSTRING(REQUST_PROCESS_CN FROM 1 FOR 10), '...') AS "rqesterProcessCn" , OPETR_ID AS "opetrId" , TRIM(PROCESS_STTUS_CODE) AS "processSttus" , TO_CHAR(PROCESS_DE, 'YY-MM-DD') AS processDe , TO_CHAR(REQUST_DE, 'YY-MM-DD') AS rqesterDe , REQUST_SJ AS "rqesterSj" FROM COMTHPROGRMCHANGEDTLS WHERE 1=1
AND PROGRM_FILE_NM LIKE CONCAT('%', #{params.searchKeyword}, '%')
) TB ) R ORDER BY RNUM DESC LIMIT #{params.recordCountPerPage} OFFSET #{params.firstIndex}

mapper.insert:

