(  PROGRM_FILE_NM
, REQUST_NO
, RQESTER_ID
, CHANGE_REQUST_CN
, REQUST_DE
, REQUST_SJ
, PROCESS_STTUS_CODE)
VALUES (  #{progrmFileNm}
       , #{rqesterNo}
       , #{rqesterPersonId}
       , #{changerqesterCn}
       , TO_DATE(#{rqesterDe}, 'YY-MM-DD')
       , #{rqesterSj}
       , 'A')

mapper.update:

UPDATE COMTHPROGRMCHANGEDTLS
SET    RQESTER_ID = #{rqesterPersonId}
  , CHANGE_REQUST_CN = #{changerqesterCn}
  , REQUST_DE = TO_DATE(#{rqesterDe}, 'YY-MM-DD')
  , REQUST_SJ = #{rqesterSj}
WHERE PROGRM_FILE_NM = #{progrmFileNm}
  AND   REQUST_NO = #{rqesterNo}

